// Generated CBOR (de)serializers for the CSIL value types.
// Code generated by csilgen; DO NOT EDIT.

/// A minimal canonical-CBOR (RFC 8949 subset) value model and codec.
public indirect enum CsilCborValue: Hashable, Sendable {
  case uint(UInt64)
  case int(Int64)
  case bool(Bool)
  case double(Double)
  case null
  case text(String)
  case bytes([UInt8])
  case array([CsilCborValue])
  case map([(CsilCborValue, CsilCborValue)])
  case tag(UInt64, CsilCborValue)

  /// Two values are equal when their canonical encodings are equal, so map entry
  /// order does not matter and the `any` core type compares the way it travels.
  public static func == (lhs: CsilCborValue, rhs: CsilCborValue) -> Bool {
    CsilCbor.encode(lhs) == CsilCbor.encode(rhs)
  }

  public func hash(into hasher: inout Hasher) {
    hasher.combine(CsilCbor.encode(self))
  }
}

/// The `any` core type and an inline shape with no Swift name: the decoded CBOR value
/// itself, so it survives a round trip unchanged.
public typealias AnyCsilValue = CsilCborValue

public enum CsilCborError: Swift.Error, CustomStringConvertible {
  case malformed
  case trailingBytes
  case missingField(String)
  case typeMismatch
  case duplicateKey(String)
  case mapKeyOrder
  case longFormKey

  public var description: String {
    switch self {
    case .malformed: return "csil cbor: malformed input"
    case .trailingBytes: return "csil cbor: trailing bytes after the value"
    case .missingField(let key): return "csil cbor: missing field \"\(key)\""
    case .typeMismatch: return "csil cbor: value does not match its type"
    case .duplicateKey(let key): return "csil cbor: duplicate key \(key)"
    case .mapKeyOrder: return "csil cbor: map keys are not in canonical order"
    case .longFormKey: return "csil cbor: map key is not in shortest form"
    }
  }
}

