      let n = Int(arg)
      let slice = Array(b[pos..<pos + n])
      pos += n
      return .bytes(slice)
    case 3:
      guard arg <= UInt64(b.count - pos) else { throw CsilCborError.malformed }
      let n = Int(arg)
